{
  "window_id": "w0036",
  "observed_failures": [
    {
      "id": "F1",
      "where": "predictions row 078.jpg",
      "symptom": "total_amount delivered as empty string \"\" instead of null; violates strict-schema null contract documented in xlsx skill",
      "evidence": "predictions.rows contains {filename: 078.jpg, total_amount: \"\"}; field_feedback marks amount_correct=false for 078.jpg"
    },
    {
      "id": "F2",
      "where": "predictions row 074.jpg amount",
      "symptom": "Predicted 702.00 while receipt image clearly shows '102.00' as Total/Subtotal/Payment; OCR misread 1→7 was selected by majority voting across 3 variants",
      "evidence": "atif_steps s0031/s0032: variant 0 = 702.0 (misread), variant 1 = 702.0 (misread), variant 2 = 102.0; voting picked 702 by count without cross-checking Subtotal:102.00 and Payment:102.00 lines that agreed with 102"
    },
    {
      "id": "F3",
      "where": "predictions row 077.jpg amount",
      "symptom": "Final value drifted between variants (23.26 vs 23.25). Image shows explicit 'Rounding Adj -0.01' and bold 'TOTAL: 23.25'. Agent's priority tiers treat 'Total (Inclusive of GST): 23.26' and 'TOTAL: 23.25' as equal-tier, then order-sensitive; feedback marks amount_correct=false",
      "evidence": "atif_steps s0031 shows both lines matched tier 3; final delivered value was 23.26"
    },
    {
      "id": "F4",
      "where": "predictions row 034.jpg date",
      "symptom": "Date predicted 2018-08-09 (interpreting '09/08/2018' as MM/DD); receipt is Malaysian (RM, GST) where DD/MM is dominant",
      "evidence": "image shows 'Date: 09/03/2018' on similar Malaysian receipts; image-ocr DATE_PATTERNS tries %d/%m/%Y first but still picks MM/DD for ambiguous strings when a %m/%d pattern happens to parse"
    },
    {
      "id": "F5",
      "where": "062/064-class debugging in s0033–s0035",
      "symptom": "Fallback 'next-line' rule for split keyword/number pulled payment lines like 'Visa RM 688.17' as the total when the TOTAL line's number was garbled",
      "evidence": "atif s0033 trace: Line 11 'Total RM = B81?' had no valid number, fallback returned 688.17 from next 'Visa RM' line; later patched by agent but not codified in skill"
    },
    {
      "id": "F6",
      "where": "run terminated at iteration 65 (max_iterations)",
      "symptom": "Agent spent >25 iterations re-tuning OCR variants and voting heuristics with no stopping rule; original Skill gave only generic multi-pass advice",
      "evidence": "execution_metadata.termination_reason='max_iterations'; response_tool_call_counts terminal=27, think=22"
    }
  ],
  "root_causes": [
    {
      "id": "R1",
      "description": "image-ocr's structured-extraction section lists EXCLUSIONS for subtotals/tax/change/cash-tendered but omits payment-instrument lines (Visa, Mastercard, Cash Received, Payment, Amount Paid, Balance, Tendered). When keyword matches on an adjacent 'TOTAL' row fail, the two-line fallback silently harvests the payment amount."
    },
    {
      "id": "R2",
      "description": "image-ocr's priority tiers put 'Total Rounded', 'Total After Rounding', 'Rounded Total (RM)' into the same bucket as generic 'TOTAL'. On receipts that print both pre-rounding and post-rounding totals (077, 039, 083, 097-style), ordering/voting alone cannot reliably prefer the final rounded value."
    },
    {
      "id": "R3",
      "description": "image-ocr documents 'multi-pass OCR' and 'combine results' but gives no concrete voting/cross-validation recipe. The agent reinvented tier+frequency voting that is brittle to OCR noise (102→702) because it never cross-checked against Subtotal/Payment/Cash lines that agreed on the correct value."
    },
    {
      "id": "R4",
      "description": "image-ocr date section tries formats in a fixed order and returns the first parseable match, but does not document ambiguity handling (DD/MM vs MM/DD) nor locale cues (RM/GST/Malaysia → DD/MM preferred). Same input 'XX/YY/ZZZZ' can parse under %m/%d/%Y when %d/%m/%Y would also parse, producing silent transpositions."
    },
    {
      "id": "R5",
      "description": "xlsx skill mentions null-not-empty-string in the pitfall list, but the strict-schema example still uses pandas default behavior that lets NaN serialize as blank or '' depending on writer path. There is no explicit anti-pattern showing total_amount=\"\" on OCR failure, and no verification snippet that asserts nullable columns never contain ''."
    },
    {
      "id": "R6",
      "description": "Neither image-ocr nor xlsx bounds the OCR-tuning effort. The skill encourages 'try multiple PSM modes / preprocessing variants / voting' without a stop criterion, so an agent can iterate until budget exhaustion on a handful of hard images."
    }
  ],
  "skill_defects": {
    "image-ocr": [
      "Exclusion list missing payment-instrument keywords (Visa, Mastercard, Credit, Debit, Cash Received, Amount Paid, Payment, Tendered, Balance Due-as-payment-line).",
      "Priority tiers do not elevate 'ROUNDED TOTAL' / 'TOTAL AFTER ROUNDING' / 'TOTAL ROUNDED' / 'NET TOTAL' / 'FINAL TOTAL' above generic 'TOTAL' when both appear.",
      "Two-line fallback is not conditioned on 'current keyword line contains no digits'; this allows payment lines to be adopted as totals when OCR garbles the real number.",
      "No cross-validation recipe: an extracted candidate is never checked against subtotal/payment/cash-change arithmetic (total ≈ subtotal + tax − rounding; total ≈ cash − change).",
      "Date extraction does not disambiguate DD/MM vs MM/DD; no locale hints (RM, GST, SST, Malaysian merchant names) and no 'use day>12 witness elsewhere in file to lock format' heuristic.",
      "Multi-pass OCR section lacks a concrete voting recipe with (tier_priority, frequency, supporting-line-agreement) scoring and lacks a hard cap on variant count.",
      "Failure contract is vague: skill shows returning None in examples but does not explicitly forbid '', 'None', 'nan', or default-zero values flowing into downstream writers."
    ],
    "xlsx": [
      "Strict-schema section lists the empty-string pitfall in prose but does not show a before/after code example of the exact bug (writing '' instead of None when extraction fails).",
      "Canonical pattern does not include a post-write assertion that nullable columns contain only strings-with-content or real Python None (no '', 'nan', 'None').",
      "No guidance on tying the extractor's failure sentinel (None) to the writer's astype('object') + to_excel path; agents frequently insert '' or NaN at the extractor boundary."
    ],
    "openai-vision": [
      "Not invoked and not responsible for the observed failures; no defects attributable from this window."
    ],
    "pdf": [
      "Not invoked and not responsible for the observed failures; no defects attributable from this window."
    ],
    "video-frame-extraction": [
      "Not invoked and not responsible for the observed failures; no defects attributable from this window."
    ]
  },
  "repair_recommendations": [
    {
      "skill": "image-ocr",
      "change": "Extend the EXCLUSIONS list for receipt/form field extraction to include payment-instrument and settlement keywords: VISA, MASTERCARD, MASTER CARD, AMEX, CREDIT CARD, DEBIT CARD, CARD, EWALLET, TNG, GRABPAY, CASH RECEIVED, CASH PAYMENT, AMOUNT PAID, PAYMENT, TENDERED, BALANCE, CHANGE DUE, ROUNDING ADJ, ROUNDING ADJUSTMENT, SERV. CHARGE, SERVICE CHARGE. Apply these exclusions both when selecting the keyword line AND when evaluating the two-line fallback target.",
      "rationale": "Prevents the fallback from harvesting the Visa/Mastercard/Cash-Received amount when the real TOTAL line is OCR-garbled (F5, R1)."
    },
    {
      "skill": "image-ocr",
      "change": "Introduce an explicit new top tier in the structured-extraction priority ladder, ABOVE 'GRAND TOTAL', for post-rounding/final/net totals: ROUNDED TOTAL, TOTAL ROUNDED, TOTAL AFTER ROUNDING, TOTAL AMT ROUNDED, NETT? TOTAL, NET TOTAL, FINAL TOTAL. Document that when both a pre-rounding and a post-rounding TOTAL appear, the post-rounding value is the authoritative final amount.",
      "rationale": "Fixes the 23.26-vs-23.25 class of errors (F3, R2) without requiring per-receipt ordering heuristics."
    },
    {
      "skill": "image-ocr",
      "change": "Codify the two-line fallback discipline: only consult the next non-empty, non-excluded line when the keyword line contains NO digits at all. If the keyword line contains digits but none parse as a valid monetary value, treat the candidate as failed and move to the next tier instead of walking forward.",
      "rationale": "Directly eliminates the 'Visa RM 688.17' fallthrough pattern (F5) and generalizes to any garbled-number TOTAL line."
    },
    {
      "skill": "image-ocr",
      "change": "Add a short 'cross-validation' subsection to structured extraction: after a candidate total is chosen, (a) compute approximate expected total from the first observed Subtotal + Tax − Rounding if those lines exist; (b) compare to Cash − Change when both are present; if the chosen candidate disagrees with these witnesses by more than a small tolerance AND a closely-matching value appears in multiple non-keyword lines of the same OCR pass, prefer the witnessed value. Keep it as a soft tiebreak, not a hard override.",
      "rationale": "Would have caught the 102→702 misread in 074 (F2, R3): Subtotal=102.00 and Payment=102.00 agree against the outlier 702.00."
    },
    {
      "skill": "image-ocr",
      "change": "Expand the date section with a disambiguation subsection. (i) Prefer DD/MM/YYYY ordering by default when locale cues are present (presence of 'RM', 'GST', 'SST', 'Sdn Bhd', Malaysian phone-number patterns, or any date in the batch with day>12 under DD/MM). (ii) If both MM/DD and DD/MM parse and no cue disambiguates, log a warning and still prefer DD/MM for Asian/European receipts; (iii) never silently flip format between receipts in the same batch — pick one convention per directory and reuse it.",
      "rationale": "Addresses 034.jpg (F4, R4) and prevents similar silent transpositions on other ambiguous dates."
    },
    {
      "skill": "image-ocr",
      "change": "Replace the open-ended 'combine all extracted text' advice with a concrete, bounded multi-variant recipe: run at most N=3 OCR variants (default + grayscale-autocontrast + 2x-upscale), extract structured candidates from each, then score each candidate by tuple (tier_priority ascending, support_count descending, variant_index ascending). Explicitly document that voting is capped at 3 variants and no further tuning is warranted — produce None if the top candidate has support_count=1 at the lowest tier and fails cross-validation.",
      "rationale": "Bounds the tuning budget (F6, R6) and formalizes the voting behavior the agent kept reinventing."
    },
    {
      "skill": "image-ocr",
      "change": "Tighten the failure contract in both the per-image pipeline and the schema: 'On any extraction failure, the field value MUST be Python None. Do not return \"\", \"None\", \"nan\", 0, or 0.0. The caller is responsible for turning None into a real null cell.' Add a one-line unit-test style example at the end of the structured-extraction section.",
      "rationale": "Removes the ambiguity that let total_amount=\"\" reach the Excel writer for 078.jpg (F1, R5)."
    },
    {
      "skill": "xlsx",
      "change": "In the Strict-Schema Outputs section, add a named 'Null handling for extraction outputs' subsection with (a) a WRONG example where a failed OCR returns '' and the agent writes df.loc[i,'total_amount']='' (showing the resulting empty-string cell), and (b) the CORRECT pattern using None + df[col].astype('object') + explicit assertion `assert not ((df[col]==\"\") | (df[col].astype(str)==\"nan\")).any()` for every nullable column.",
      "rationale": "Makes the 078.jpg-style defect (F1, R5) impossible to miss during self-check."
    },
    {
      "skill": "xlsx",
      "change": "Extend the post-write verification snippet in the canonical pattern to re-read with pandas AND with openpyxl and assert that cells intended to be null report as NaN/None (never ''), and that non-null numeric-string fields match the exact N-decimal format required by the task.",
      "rationale": "Catches writer-path differences (openpyxl vs pandas default) before delivery and prevents silent contract drift."
    },
    {
      "skill": "image-ocr",
      "change": "Add an explicit 'Stop criterion' note in the multi-pass section: once the top-ranked candidate is both the highest-priority tier AND confirmed by cross-validation or by agreement across >=2 OCR variants, do not generate further variants or hand-tune regex for that receipt. If after the bounded recipe the result is still unconfirmed, emit None rather than iterating.",
      "rationale": "Prevents the max_iterations termination mode (F6, R6) and keeps agent runs within budget."
    }
  ],
  "confidence": {
    "level": "medium-high",
    "notes": "F1 (empty-string for 078) is directly visible in predictions and is a clear schema contract breach. F2, F3, F5 are supported by the agent's own OCR traces in atif_steps s0031–s0035 and by inspection of the supplied receipt images. F4 relies on standard DD/MM Malaysian receipt convention — plausible but not verifiable without the oracle date; the recommended fix is conservative and would not harm correct cases. F6 is grounded in execution_metadata (termination_reason=max_iterations, 65 iterations) and the skill's open-ended tuning guidance. Recommendations are scoped to the five existing SKILL.md files only."
  }
}
